1:26.457Z","review_batch":"nl-scale-20261102-031"}},{"ref":"w1","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL52940W"},"before":null,"after":{"title":"The Hard Way","author_id":380,"first_publish_year":2006,"open_library_id":"OL52940W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL52940W"}},{"ref":"e1","relation":"editions","key":{"open_library_edition_id":"OL47268856M"},"before":null,"after":{"work_id":"@w1","open_library_edition_id":"OL47268856M","isbn_13":"9789024553952","isbn_10":null,"title":"Bloedgeld","language":"dut","publisher":"Luitingh"}},{"ref":"d1","relation":"catalog_work_descriptions","key":{"work_id":"@w1","language":"nl"},"before":null,"after":{"work_id":"@w1","language":"nl","bound_author_id":380,"text":"Een toevallige waarneming in New York betrekt Jack Reacher bij een ontvoeringszaak. Edward Lane heeft losgeld betaald om zijn vrouw en kind terug te krijgen en schakelt Reacher in om de dader te vinden. Tijdens het onderzoek blijkt Lane zelf verbonden aan een wereld van huurlingen en verborgen belangen. Zijn verhaal roept steeds meer vragen op. Reacher moet vaststellen welke informatie betrouwbaar is terwijl hij probeert de ontvoerde mensen levend terug te vinden.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.penguinrandomhouse.com/books/27127/the-hard-way-by-lee-child/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p296471801"],"reference":"new-work-dossier-readings-031.json#39","checked_at":"2026-11-02T23:01:26.457Z","note":"Exact Dutchpaperback9789024553952/KBp296471801 explicitly translates TheHardWay2006, JackReacher#10. OriginalPublisher and authoragent confirm ransom/EdwardLane narrative. No association with another Bloedgeld title and no inference of language from English author or title."},{"type":"original_substantive_sourc